import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || resolve('data/workboard.sqlite');
mkdirSync(dirname(databasePath), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
const projectQuery = `SELECT projects.id, projects.name, projects.archived,
  COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id`;
const listProjects = db.prepare(`${projectQuery} GROUP BY projects.id ORDER BY projects.id`);
const findProject = db.prepare(`${projectQuery} WHERE projects.id = ? GROUP BY projects.id`);
const updateProject = db.prepare('UPDATE projects SET name = ?, archived = ? WHERE id = ?');
const projectJson = (project) => ({ ...project, archived: Boolean(project.archived) });
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = db.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET title = ?, completed = ?, priority = ? WHERE project_id = ? AND id = ?');
const taskJson = (task) => ({ ...task, completed: Boolean(task.completed) });

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all().map(projectJson));
    }
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return json(response, project ? 200 : 404, project ? projectJson(project) : { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && match) {
      if (!findProject.get(match[1])) return json(response, 404, { error: 'Project not found' });
      const input = await readJson(request);
      const project = findProject.get(match[1]);
      const renaming = Object.hasOwn(input ?? {}, 'name');
      const archiving = Object.hasOwn(input ?? {}, 'archived');
      if (renaming && project.archived) {
        return json(response, 409, { error: 'Archived project' });
      }
      const name = renaming && typeof input.name === 'string' ? input.name.trim() : '';
      if (renaming && !name) {
        return json(response, 400, { error: 'Project name is required' });
      }
      if ((!renaming && !archiving) || (archiving && typeof input.archived !== 'boolean')) {
        return json(response, 400, { error: 'Archive state must be a boolean' });
      }
      updateProject.run(renaming ? name : project.name,
        archiving ? Number(input.archived) : project.archived, match[1]);
      return json(response, 200, projectJson(findProject.get(match[1])));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project' });
      }
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readJson(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title);
        return json(response, 201, taskJson(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (request.method === 'PATCH' && taskId) {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const task = findTask.get(projectId, taskId);
        const renaming = Object.hasOwn(input ?? {}, 'title');
        const completing = Object.hasOwn(input ?? {}, 'completed');
        const prioritizing = Object.hasOwn(input ?? {}, 'priority');
        const title = renaming && typeof input.title === 'string' ? input.title.trim() : '';
        if (renaming && !title) {
          return json(response, 400, { error: 'Task title is required' });
        }
        if ((!renaming && !completing && !prioritizing) || (completing && typeof input.completed !== 'boolean')) {
          return json(response, 400, { error: 'Completion must be a boolean' });
        }
        if (prioritizing && !['Low', 'Normal', 'High'].includes(input.priority)) {
          return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        updateTask.run(renaming ? title : task.title,
          completing ? Number(input.completed) : task.completed,
          prioritizing ? input.priority : task.priority, projectId, taskId);
        return json(response, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectJson(findProject.get(Number(result.lastInsertRowid))));
    }
    const asset = assets.get(path) || (/^\/projects\/\d+$/.test(path) ? assets.get('/') : undefined);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[0] });
      return response.end(asset[1]);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Something went wrong' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}
const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}

async function api(path, options) {
  const response = await fetch(path, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Unable to load Workboard');
  return result;
}

function projectRow(project, onArchive, showError) {
  const row = element('div', undefined, { 'data-testid': 'project-row', class: 'project-row' });
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const details = element('div', undefined, { class: 'project-details' });
  details.append(element('span', project.name), element('span',
    `${project.completed_count}/${project.total_count} completed`, { 'data-testid': 'project-summary', class: 'summary' }));
  const actions = element('div', undefined, { class: 'project-actions' });
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      onArchive();
    } catch (error) {
      showError(error);
      archive.disabled = false;
    }
  });
  actions.append(open, archive);
  row.append(details, actions);
  return row;
}

function renderRename(project, heading) {
  const form = element('form', undefined, { class: 'rename-form' });
  const input = element('input', undefined, {
    id: 'new-project-name', name: 'name', type: 'text', autocomplete: 'off',
  });
  input.value = project.name;
  input.disabled = project.archived;
  const rename = element('button', 'Rename project', { type: 'submit' });
  rename.disabled = project.archived;
  const controls = element('div', undefined, { class: 'controls' });
  controls.append(input, rename);
  const alert = element('p', '', { role: 'alert', class: 'alert' });
  alert.hidden = true;
  form.append(element('label', 'New project name', { for: 'new-project-name' }), controls, alert);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    rename.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = project.name;
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    } finally {
      rename.disabled = project.archived;
    }
  });
  app.append(form);
}

async function renderTasks(projectId, archived) {
  const form = element('form');
  const input = element('input', undefined, { id: 'task-title', name: 'title', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create task', { type: 'submit', class: 'primary' });
  create.disabled = true;
  const controls = element('div', undefined, { class: 'controls' });
  controls.append(input, create);
  const alert = element('p', '', { role: 'alert', class: 'alert' });
  alert.hidden = true;
  form.append(element('label', 'Task title', { for: 'task-title' }), controls, alert);
  const filterControls = element('div', undefined, { class: 'task-filter' });
  const filter = element('select', undefined, { id: 'task-filter' });
  for (const value of ['All', 'Open', 'Completed']) {
    filter.append(element('option', value, { value }));
  }
  filter.value = 'All';
  filterControls.append(element('label', 'Task filter', { for: 'task-filter' }), filter);
  const priorityFilterControls = element('div', undefined, { class: 'task-filter' });
  const priorityFilter = element('select', undefined, { id: 'priority-filter' });
  for (const value of ['All', 'Low', 'Normal', 'High']) {
    priorityFilter.append(element('option', value, { value }));
  }
  priorityFilter.value = 'All';
  priorityFilterControls.append(element('label', 'Priority filter', { for: 'priority-filter' }), priorityFilter);
  const list = element('section', undefined, { 'aria-label': 'Tasks', class: 'task-list' });
  app.append(form, filterControls, priorityFilterControls, list);
  const path = `/api/projects/${projectId}/tasks`;
  const tasks = await api(path);

  function showError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }

  function refresh() {
    const visible = tasks.filter((task) =>
      (filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed)) &&
      (priorityFilter.value === 'All' || task.priority === priorityFilter.value));
    list.replaceChildren(...visible.map((task) => {
      const row = element('div', undefined, { 'data-testid': 'task-row', class: 'task-row' });
      const checkbox = element('input', undefined, {
        type: 'checkbox', 'aria-label': `Complete ${task.title}`,
      });
      checkbox.checked = task.completed;
      checkbox.disabled = archived;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
        } catch (error) {
          showError(error);
        } finally {
          refresh();
        }
      });
      row.append(checkbox, element('span', task.title));
      const priorityControls = element('div', undefined, { class: 'task-priority' });
      const priority = element('select', undefined, { id: `task-priority-${task.id}` });
      for (const value of ['Low', 'Normal', 'High']) {
        priority.append(element('option', value, { value }));
      }
      priority.value = task.priority;
      priority.disabled = archived;
      priority.addEventListener('change', async () => {
        priority.disabled = true;
        alert.hidden = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          task.priority = saved.priority;
        } catch (error) {
          showError(error);
        } finally {
          refresh();
        }
      });
      priorityControls.append(element('label', 'Task priority', { for: priority.id }), priority);
      row.append(priorityControls);
      const renameForm = element('form', undefined, { class: 'task-rename-form' });
      const renameInput = element('input', undefined, {
        id: `new-task-title-${task.id}`, type: 'text', name: 'title', autocomplete: 'off',
      });
      renameInput.value = task.title;
      renameInput.disabled = archived;
      const rename = element('button', 'Rename task', { type: 'submit' });
      rename.disabled = archived;
      const renameControls = element('div', undefined, { class: 'controls' });
      renameControls.append(renameInput, rename);
      renameForm.append(element('label', 'New task title', { for: renameInput.id }), renameControls);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (archived) return;
        alert.hidden = true;
        const title = renameInput.value.trim();
        if (!title) {
          showError(new Error('Task title is required'));
          renameInput.focus();
          return;
        }
        rename.disabled = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title }),
          });
          Object.assign(task, saved);
          refresh();
        } catch (error) {
          showError(error);
        } finally {
          rename.disabled = archived;
        }
      });
      row.append(renameForm);
      return row;
    }));
    if (!visible.length) list.append(element('p', 'No tasks to show.', { class: 'empty' }));
  }

  filter.addEventListener('change', refresh);
  priorityFilter.addEventListener('change', refresh);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (archived) return;
    alert.hidden = true;
    const title = input.value.trim();
    if (!title) {
      showError(new Error('Task title is required'));
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      tasks.push(await api(path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }));
      refresh();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(error);
    } finally {
      create.disabled = archived;
    }
  });
  refresh();
  create.disabled = archived;
}

async function render() {
  app.replaceChildren();
  const projectId = window.location.pathname.match(/^\/projects\/(\d+)$/)?.[1];
  if (projectId) {
    const back = element('button', 'Projects', { type: 'button', class: 'back' });
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back);
    const project = await api(`/api/projects/${projectId}`);
    document.title = `${project.name} · Workboard`;
    const heading = element('h1', project.name);
    app.append(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    renderRename(project, heading);
    await renderTasks(projectId, project.archived);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create project', { type: 'submit', class: 'primary' });
  create.disabled = true;
  const controls = element('div', undefined, { class: 'controls' });
  controls.append(input, create);
  const alert = element('p', '', { role: 'alert', class: 'alert' });
  alert.hidden = true;
  form.append(label, controls, alert);
  const filterControls = element('div', undefined, { class: 'project-filter' });
  const filter = element('select', undefined, { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) {
    filter.append(element('option', value, { value }));
  }
  filter.value = 'Active';
  filterControls.append(element('label', 'Project filter', { for: 'project-filter' }), filter);
  const list = element('section', undefined, { 'aria-label': 'Projects', class: 'project-list' });
  app.append(form, filterControls, list);
  const projects = await api('/api/projects');
  function showError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
  function refresh() {
    const visible = projects.filter((project) => project.archived === (filter.value === 'Archived'));
    list.replaceChildren(...visible.map((project) => projectRow(project, refresh, showError)));
    if (!visible.length) list.append(element('p', filter.value === 'Archived'
      ? 'No archived projects.' : 'No projects yet. Create a project to get started.', { class: 'empty' }));
  }
  filter.addEventListener('change', refresh);
  refresh();

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      refresh();
      input.value = '';
      input.focus();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    } finally {
      create.disabled = false;
    }
  });
  create.disabled = false;
}

render().catch((error) => {
  app.append(element('p', error.message, { role: 'alert', class: 'alert' }));
}).finally(() => app.setAttribute('aria-busy', 'false'));
