# Workboard

Requires Node.js 22.22.1. Uses built-in HTTP and SQLite with no external dependencies.

```sh
npm start
```

The server binds to `0.0.0.0` on `PORT` (default `8080`). Set `DB_PATH` to select the persistent SQLite file (default `data/workboard.sqlite`). For example:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

Open `/` to create and browse projects, view completion summaries, and archive or restore projects. Open an active project to rename it, create or rename tasks, toggle completion, choose each task's Low, Normal, or High priority, and combine the All/Open/Completed task filter with the All/Low/Normal/High priority filter. Both filters initially select All. Edits immediately update matching rows without resetting either filter; summaries always count every task. Existing and new tasks default to Normal priority. Archived projects allow viewing and filtering tasks, with renaming and task changes disabled. Renaming preserves identity, position, completion, and priority. All changes persist across server restarts. `GET /health` returns `{"status":"ok"}`.

Run the HTTP and persistence checks with:

```sh
npm test
```
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runInNewContext } from 'node:vm';

// Exercise the browser's actual rendering and event handlers without dependencies.
class Node {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.attributes = {};
    this.events = {};
    this.value = '';
    this.disabled = false;
  }
  setAttribute(key, value) {
    this.attributes[key] = value;
    if (key === 'id') this.id = value;
  }
  append(...nodes) { this.children.push(...nodes); }
  replaceChildren(...nodes) { this.children = nodes; }
  addEventListener(event, handler) { this.events[event] = handler; }
  focus() {}
  async dispatch(event) { await this.events[event]({ preventDefault() {} }); }
}

function descendants(node) {
  return [node, ...node.children.flatMap(descendants)];
}
const find = (node, predicate) => descendants(node).find(predicate);
const byId = (node, id) => find(node, (child) => child.id === id);
const rows = (app) => descendants(app).filter((node) => node.attributes['data-testid'] === 'task-row');
const titles = (app) => rows(app).map((row) => row.children.find((node) => node.tag === 'span').textContent);
const source = await readFile(new URL('../public/app.js', import.meta.url), 'utf8');

async function page(archived = false) {
  const app = new Node('main');
  const tasks = ['Low', 'Normal', 'High'].flatMap((priority, index) => [false, true].map((completed, offset) => ({
    id: index * 2 + offset + 1, project_id: 1, title: `${priority} ${completed ? 'completed' : 'open'}`,
    priority, completed,
  })));
  const writes = [];
  const context = {
    document: { querySelector: () => app, createElement: (tag) => new Node(tag) },
    window: { location: { pathname: '/projects/1' } },
    fetch: async (path, options) => {
      let result;
      if (options) {
        assert.equal(archived, false, 'archived filtering must never edit data');
        const input = JSON.parse(options.body);
        writes.push({ path, input });
        if (options.method === 'POST') {
          result = { id: tasks.length + 1, project_id: 1, title: input.title.trim(), completed: false, priority: 'Normal' };
          tasks.push(result);
        } else {
          result = tasks.find((task) => task.id === Number(path.split('/').at(-1)));
          Object.assign(result, input);
        }
      } else if (path.endsWith('/tasks')) result = tasks;
      else result = { id: 1, name: 'Filters', archived, total_count: 6, completed_count: 3 };
      return { ok: true, json: async () => structuredClone(result) };
    },
  };
  runInNewContext(source, context);
  await new Promise((resolve) => setImmediate(resolve));
  assert.equal(app.attributes['aria-busy'], 'false');
  return { app, tasks, writes };
}

